const db = require('better-sqlite3')('/workspace/world.db');

// 1. Update CI-0006 quantity from 3 to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006'\").run();
console.log('✅ CI-0006 quantity updated: 3 → 2');

// 2. Remove CI-0005 from cart_items
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0005'\").run();
console.log('✅ CI-0005 removed from cart');

// 3. Recalculate cart totals
//    CI-0006: 2 × \$89 = \$178
//    CI-0007: 2 × \$72 = \$144
//    New subtotal = \$322
const newSubtotal = (2 * 89) + (2 * 72);  // 178 + 144 = 322
const newItemIds = JSON.stringify(['CI-0006', 'CI-0007']);

db.prepare(\"UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = 'CART-user_58b0a2d6'\")
  .run(newSubtotal, newSubtotal, newItemIds);
console.log('✅ Cart totals updated');

// 4. Verify final state
console.log('\n=== UPDATED CART ===');
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log(JSON.stringify(cart, null, 2));

console.log('\n=== REMAINING CART ITEMS ===');
const items = db.prepare(\"SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all();
items.forEach(i => console.log(JSON.stringify(i)));
"
